arguments.argument:
if(data_path!="")
{
    if(spm_path!="")
    {
        //LZH
        lh5_path = filename_change_ext(spm_path, "")+".lzh"
        file_delete(lh5_path)
        execute_program("lha.ex_", "a -1 "+chr(34)+lh5_path+chr(34)+" "+chr(34)+data_path+chr(34), true)
        
        //Write LZH to SPM
        spm_file = file_bin_open(spm_path, 0)
        file_bin_seek(spm_file, 1130)
        length = file_bin_read_int(spm_file)
        file_bin_seek(spm_file, file_bin_position(spm_file)+length)
        length = file_bin_read_int(spm_file)
        file_bin_seek(spm_file, file_bin_position(spm_file)+length)
        max_number = file_bin_read_int(spm_file)
        repeat(max_number)
        {
            type = file_bin_read_short(spm_file)
            number = file_bin_read_int(spm_file)
            repeat(number)
            {
                string_number = file_bin_read_byte(spm_file)
                repeat(string_number+1)
                {
                    length = file_bin_read_int(spm_file)
                    file_bin_seek(spm_file, file_bin_position(spm_file)+length)
                }
            }
        }
        lh5_start = file_bin_position(spm_file)
        file_bin_seek(spm_file, lh5_start+2)
        lh5 = file_bin_read_char(spm_file, 5)
        if(lh5=="-lh5-")
        {
            //New SPM Making
            new_spm_path = spm_path+".new"
            file_delete(new_spm_path)
            
            file_bin_seek(spm_file, 0)
            
            new_spm_file = file_bin_open(new_spm_path, 1)
            lh5_file = file_bin_open(lh5_path, 0)
            repeat(lh5_start)
            {
                file_bin_write_byte(new_spm_file, file_bin_read_byte(spm_file))
            }
            repeat(file_bin_size(lh5_file))
            {
                file_bin_write_byte(new_spm_file, file_bin_read_byte(lh5_file))
            }
            file_bin_close(lh5_file)
            file_bin_close(new_spm_file)
            
            file_bin_close(spm_file)
            
            file_delete(spm_path)
            file_delete(lh5_path)
            file_rename(new_spm_path, spm_path)
            
            if(done_message){wd_message_simple("SPM Packing is Complete!")}
        }
        else
        {
            wd_message_simple("SPM Header Error!")
            file_bin_close(spm_file)
        }
    }
    else
    {
        wd_message_simple("SPM Path Error!")
    }
}
else
{
    wd_message_simple("DATA Path Error!")
}
